const KEY='ai-request-desk-v2';let lang='de',rows=[],selected='',blocked=false,dirty=false,toastTimer,storedSnapshot=null;
const $=id=>document.getElementById(id),t=k=>dictionaries[lang][k]||k;
function text(tag,value,cls){const e=document.createElement(tag);e.textContent=value;if(cls)e.className=cls;return e;}
function status(r){return t(r.status+'Status');}
function money(cents){return cents===null||cents===undefined?t('unknownAmount'):new Intl.NumberFormat(lang,{style:'currency',currency:'EUR'}).format(cents/100);}
function toast(s){$('toast').textContent=s;$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>{$('toast').hidden=true},9000);}
function store(candidate){if(blocked)throw Error('storage');try{if(localStorage.getItem(KEY)!==storedSnapshot)throw Error('stale');const next=E.serialize(candidate);localStorage.setItem(KEY,next);storedSnapshot=next;}catch(e){blocked=true;throw Error('storage')}rows=candidate;}
function mutate(id,fn){try{const candidate=E.restore(E.serialize(rows));const r=candidate.find(x=>x.id===id);fn(r);store(candidate);dirty=false;render();toast(t('saved'));}catch(e){toast(t(e.message==='storage'?'storageError':'invalid'))}}
function canLeave(){return !dirty||confirm(t('unsavedQuestion'));}
function badge(r){return text('span',status(r),'badge '+r.status);}
function button(label,fn,cls=''){let b=text('button',label,cls);b.type='button';b.onclick=fn;b.disabled=blocked;return b;}
function init(){try{const savedLang=localStorage.getItem('desk-language');if(E.LANGS.includes(savedLang))lang=savedLang;const saved=localStorage.getItem(KEY);storedSnapshot=saved;rows=saved?E.restore(saved):E.seed(lang);if(!saved)store(rows);}catch(e){blocked=true;rows=E.seed(lang);}selected=rows[0]?.id||'';render();if(blocked)toast(t('storageError'));}
function render(){document.documentElement.lang=lang;$('ui-lang').value=lang;const map={'language-label':'language','workspace-label':'workspace','inbox-nav':'inbox','side-title':'sideTitle','side-desc':'sideDesc','local-label':'local','eyebrow':'eyebrow','heading':'heading','subheading':'subheading','new-request':'new','learning-title':'learningTitle','learning-desc':'learningDesc','metric-total-label':'total','metric-review-label':'reviewCount','metric-approved-label':'approvedCount','queue-heading':'queue','search-label':'search','filter-label':'filter','reset':'reset','compose-title':'compose','close-compose':'close','subject-label':'subject','body-label':'body','create-lang-label':'replyLanguage','create-button':'create','about-eyebrow':'aboutEyebrow','about-title':'aboutTitle','about-desc':'aboutDesc','rules-title':'rulesTitle','footer-note':'footer'};for(const [id,key]of Object.entries(map))$(id).textContent=t(key);$('search').placeholder=t('search');$('body').placeholder=t('inputHint');let filter=$('filter').value||'all';$('filter').replaceChildren();for(const value of ['all','new','review','approved','deferred','error']){let option=text('option',value==='all'?t('all'):t(value+'Status'));option.value=value;$('filter').append(option)}$('filter').value=filter;$('metric-total').textContent=rows.length;$('metric-review').textContent=rows.filter(r=>r.status==='review').length;$('metric-approved').textContent=rows.filter(r=>r.status==='approved').length;$('rules-list').replaceChildren(...dictionaries[lang].rules.map(x=>text('li',x)));$('create-button').disabled=blocked;$('new-request').disabled=blocked;$('reset').disabled=blocked;renderQueue();renderDetail();}
function renderQueue(){const root=$('queue'),needle=$('search').value.toLowerCase(),filter=$('filter').value;root.replaceChildren();const visible=rows.filter(r=>(filter==='all'||r.status===filter)&&(r.subject+' '+r.body).toLowerCase().includes(needle));$('queue-count').textContent=visible.length;if(!visible.length)root.append(text('p',t('noRows'),'empty'));for(const r of visible){let b=button('',()=>{if(!canLeave())return;dirty=false;selected=r.id;renderQueue();renderDetail();if(innerWidth<740)$('detail').scrollIntoView({behavior:'smooth',block:'start'})},'queue-row'+(r.id===selected?' selected':''));b.disabled=false;b.setAttribute('aria-pressed',r.id===selected?'true':'false');b.append(badge(r),text('h3',r.subject),text('small',new Date(r.created).toLocaleDateString(lang)));root.append(b)}}
function renderDetail(){const root=$('detail');root.replaceChildren();const r=rows.find(x=>x.id===selected);if(!r){root.append(text('p',t('noDetail'),'empty'));return}let head=text('div','','detail-header'),title=text('div','');title.append(text('span',r.id.startsWith('sample-')?'DEMO · '+r.id:r.id.slice(0,8),'request-id'),text('h2',r.subject));head.append(title,badge(r));root.append(head,text('h3',t('original'),'section-title'),text('p',r.body,'original'));
if(r.status==='error')root.append(text('p',t('errorNote'),'error-box'));if(r.status==='deferred')root.append(text('p',t('deferredNote'),'result'));
if(r.status!=='approved'){let actions=text('div','','actions');actions.append(button(r.status==='error'?t('retry'):t('analyze'),()=>{if(canLeave())mutate(r.id,x=>E.process(x))},'primary'),button(t('fail'),()=>{if(canLeave())mutate(r.id,x=>E.process(x,{fail:true}))},'ghost'));root.append(actions)}
if(r.analysis){let block=text('div','','review-block');block.append(text('h3',t('result'),'section-title'),text('span',t('demoMode')+' · '+t(r.analysis.category),'badge'));let result=text('div','','result '+r.analysis.check.kind);result.append(text('p',E.resultText(r,lang)));block.append(result);let check=r.analysis.check;if(check.invoiceId){let grid=text('div','','invoice-grid');for(const [label,value]of [[t('record'),check.invoiceId],[t('stated'),money(check.amount)],[t('expected'),money(check.record?.amount)]]){let box=text('div','');box.append(text('span',label),text('strong',value));grid.append(box)}block.append(grid)}
let heading=text('div','','draft-heading'),label=text('label',t('draft'));label.htmlFor='draft';heading.append(label);let select=text('select','');select.id='reply-lang';select.setAttribute('aria-label',t('replyLanguage'));for(const [value,name]of [['de','Deutsch'],['en','English'],['ru','Русский'],['uk','Українська']]){let op=text('option',name);op.value=value;select.append(op)}select.value=r.replyLang;select.disabled=r.status!=='review'||blocked;select.onchange=()=>{let value=select.value;if(confirm(t('changeQuestion')))mutate(r.id,x=>E.setReplyLanguage(x,value));else select.value=r.replyLang};heading.append(select);block.append(heading);let draft=text('textarea','');draft.id='draft';draft.value=r.draft;draft.maxLength=3000;draft.rows=5;draft.readOnly=r.status!=='review';draft.oninput=()=>{dirty=draft.value!==r.draft;let box=$('review-check'),approve=$('approve-button');if(box)box.checked=false;if(approve)approve.disabled=true};block.append(draft,text('p',t('draftNote'),'saved-note'));
if(r.status==='review'){let cb=text('label','','checkbox');let box=document.createElement('input');box.type='checkbox';box.id='review-check';box.disabled=blocked;cb.append(box,text('span',t('checked')));block.append(cb);let actions=text('div','','actions'),save=button(t('saveDraft'),()=>mutate(r.id,x=>E.setDraft(x,draft.value))),approve=button(t('approve'),()=>mutate(r.id,x=>E.approve(x,{reviewed:box.checked,draft:draft.value,expectedRevision:r.revision,reviewer:'Portfolio reviewer'})),'primary');approve.id='approve-button';approve.disabled=true;approve.title=t('noSend');box.onchange=()=>{approve.disabled=blocked||!box.checked||!draft.value.trim()};actions.append(save,approve,button(t('defer'),()=>{if(canLeave())mutate(r.id,x=>E.defer(x))},'ghost'));block.append(actions)}
if(r.status==='approved'){block.append(text('p',t('approvedNote'),'approved-note'),button(t('export'),()=>{const blob=new Blob([r.subject+'\n\n'+r.draft],{type:'text/plain;charset=utf-8'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='approved-demo-response.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}));}root.append(block)}
let audit=text('details','','audit');audit.append(text('summary',t('audit')));for(const ev of r.events){let row=text('div','','audit-row');row.append(text('strong',t(ev.action)),text('small',new Date(ev.at).toLocaleString(lang)));audit.append(row)}root.append(audit);let directory=text('details','','audit');directory.append(text('summary',t('learnMore')));for(const [i,inv]of E.INVOICES.entries()){let row=text('div','','audit-row');row.append(text('strong',inv.id+' · '+money(inv.amount)),text('small',t('service'+(i+1))));directory.append(row)}root.append(directory);}
$('ui-lang').onchange=()=>{let chosen=$('ui-lang').value;if(!canLeave()){$('ui-lang').value=lang;return}dirty=false;lang=chosen;try{localStorage.setItem('desk-language',lang)}catch{}render()};$('search').oninput=renderQueue;$('filter').onchange=renderQueue;
$('new-request').onclick=()=>{if(!canLeave())return;$('composer').hidden=false;$('subject').focus()};$('close-compose').onclick=()=>{$('composer').hidden=true};
$('request-form').onsubmit=e=>{e.preventDefault();try{let r=E.create($('subject').value,$('body').value,$('create-lang').value);store([r,...rows]);selected=r.id;dirty=false;e.target.reset();$('composer').hidden=true;render();$('detail').scrollIntoView({block:'start',behavior:'smooth'});toast(t('saved'))}catch(e){toast(t(e.message==='storage'?'storageError':'invalid'))}};
$('reset').onclick=()=>{if(!confirm(t('resetQuestion')))return;try{store(E.seed(lang));selected=rows[0].id;dirty=false;$('search').value='';$('filter').value='all';render()}catch{toast(t('storageError'))}};
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue=''}});init();
